package br.com.onda;
import org.junit.Test;
import static org.junit.Assert.*;
import java.io.*;
import java.net.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.util.*;
import java.util.concurrent.atomic.AtomicInteger;

/** Real local HTTP responses, including premature EOF, with HTTPS URL validation kept in production. */
public class ResilientDownloadTest {
 interface Handler {void reply(int index,Map<String,String> headers,OutputStream out)throws IOException;}
 static final class Server implements AutoCloseable {
  final ServerSocket socket=new ServerSocket(0,20,InetAddress.getLoopbackAddress());final List<Map<String,String>> requests=Collections.synchronizedList(new ArrayList<>());final Thread thread;volatile boolean closed;
  Server(Handler handler)throws IOException{thread=new Thread(()->{while(!closed)try(Socket s=socket.accept()){s.setSoTimeout(4000);BufferedReader reader=new BufferedReader(new InputStreamReader(s.getInputStream(),StandardCharsets.US_ASCII));String first=reader.readLine();if(first==null)continue;Map<String,String> headers=new HashMap<>();String line;while((line=reader.readLine())!=null&&!line.isEmpty()){int colon=line.indexOf(':');if(colon>0)headers.put(line.substring(0,colon).toLowerCase(Locale.ROOT),line.substring(colon+1).trim());}int index=requests.size();requests.add(headers);handler.reply(index,headers,s.getOutputStream());}catch(IOException ignored){}},"download-fixture");thread.setDaemon(true);thread.start();}
  HttpURLConnection open(URL original)throws IOException{return (HttpURLConnection)new URL("http",socket.getInetAddress().getHostAddress(),socket.getLocalPort(),original.getFile()).openConnection();}
  @Override public void close()throws Exception{closed=true;socket.close();thread.join(2000);}
 }
 static class Control implements ResilientDownload.Control {
  final List<Integer> retries=new ArrayList<>();final List<Long> pauses=new ArrayList<>();boolean cancelled;long received;
  public void check()throws IOException{if(cancelled)throw new InterruptedIOException("Cancelado");}
  public void opened(HttpURLConnection c){}public void closed(HttpURLConnection c){}
  public void bytes(int count,long stored,long expected)throws IOException{check();received+=count;}
  public void retry(int number,long stored)throws IOException{check();retries.add(number);}
 }
 static class Reset extends HttpURLConnection {
  Reset(URL u){super(u);}public void connect(){}public void disconnect(){}public boolean usingProxy(){return false;}@Override public int getResponseCode()throws IOException{throw new SocketException("Connection reset");}
 }
 static byte[] data(int count,int seed){byte[] a=new byte[count];new Random(seed).nextBytes(a);return a;}
 static long offset(Map<String,String> h){return Long.parseLong(h.get("range").substring(6).split("-")[0]);}
 static void headers(OutputStream out,int status,long length,String extra)throws IOException{out.write(("HTTP/1.1 "+status+" Response\r\nContent-Length: "+length+"\r\nConnection: close\r\n"+extra+"\r\n").getBytes(StandardCharsets.US_ASCII));out.flush();}
 static void part(OutputStream out,byte[] bytes,long start,long end,int send,String tag)throws IOException{headers(out,206,end-start+1,"Content-Range: bytes "+start+"-"+end+"/"+bytes.length+"\r\nETag: "+tag+"\r\n");out.write(bytes,(int)start,send);out.flush();}
 static void full(OutputStream out,byte[] bytes)throws IOException{headers(out,200,bytes.length,"");out.write(bytes);out.flush();}
 static File target()throws IOException{return File.createTempFile("onda-recovery-",".part");}
 static void fetch(File f,long limit,Control c,ResilientDownload.Factory factory)throws IOException{ResilientDownload.fetch("https://fixture.test/media",f,limit,"Onda-Test",c,factory,ms->c.pauses.add(ms));}
 @Test public void connectionResetIsRetried()throws Exception{byte[] bytes=data(8192,1);Control c=new Control();AtomicInteger calls=new AtomicInteger();File f=target();try(Server s=new Server((i,h,out)->full(out,bytes))){fetch(f,100000,c,url->calls.getAndIncrement()==0?new Reset(url):s.open(url));assertArrayEquals(bytes,Files.readAllBytes(f.toPath()));assertEquals(2,calls.get());assertEquals(Arrays.asList(1),c.retries);assertEquals(Arrays.asList(600L),c.pauses);}finally{f.delete();}}
 @Test public void truncatedResponseResumesWithoutDuplicatingBytes()throws Exception{byte[] bytes=data(8192,2);File f=target();Control c=new Control();try(Server s=new Server((i,h,out)->{long start=offset(h);part(out,bytes,start,bytes.length-1,i==0?1024:bytes.length-(int)start,"\"a\"");})){fetch(f,100000,c,s::open);assertArrayEquals(bytes,Files.readAllBytes(f.toPath()));assertEquals(2,s.requests.size());assertTrue(s.requests.get(1).get("range").startsWith("bytes=1024-"));assertEquals("\"a\"",s.requests.get(1).get("if-range"));assertEquals("identity",s.requests.get(0).get("accept-encoding"));assertEquals("close",s.requests.get(0).get("connection"));}finally{f.delete();}}
 @Test public void ignoredRangeRestartsInsteadOfAppending()throws Exception{byte[] old=data(8192,3),replacement=data(512,4);File f=target();Control c=new Control();try(Server s=new Server((i,h,out)->{if(i==0)part(out,old,0,old.length-1,1024,"\"a\"");else full(out,replacement);})){fetch(f,100000,c,s::open);assertArrayEquals(replacement,Files.readAllBytes(f.toPath()));assertEquals(replacement.length,f.length());}finally{f.delete();}}
 @Test public void changedEtagStartsCleanly()throws Exception{byte[] a=data(8192,5),b=data(8192,6);File f=target();Control c=new Control();try(Server s=new Server((i,h,out)->{long start=offset(h);part(out,i==0?a:b,start,b.length-1,i==0?1024:i==1?0:b.length,"\""+(i==0?"a":"b")+"\"");})){fetch(f,100000,c,s::open);assertArrayEquals(b,Files.readAllBytes(f.toPath()));assertEquals(3,s.requests.size());assertTrue(s.requests.get(2).get("range").startsWith("bytes=0-"));assertEquals(Arrays.asList(1,2),c.retries);}finally{f.delete();}}
 @Test public void wrongContentRangeIsRejected()throws Exception{File f=target();Control c=new Control();try(Server s=new Server((i,h,out)->{headers(out,206,2,"Content-Range: bytes 1-2/3\r\n");out.write(new byte[]{1,2});})){try{fetch(f,10000,c,s::open);fail();}catch(ProtocolException expected){}assertEquals(1,s.requests.size());assertEquals(0,f.length());assertTrue(c.retries.isEmpty());}finally{f.delete();}}
 @Test public void forbiddenResponseIsNotRetried()throws Exception{File f=target();Control c=new Control();try(Server s=new Server((i,h,out)->headers(out,403,0,""))){try{fetch(f,10000,c,s::open);fail();}catch(IOException e){assertTrue(e.getMessage().contains("403"));}assertEquals(1,s.requests.size());assertTrue(c.retries.isEmpty());}finally{f.delete();}}
 @Test public void stopsAfterTwoReconnections()throws Exception{File f=target();Control c=new Control();AtomicInteger calls=new AtomicInteger();try{try{fetch(f,10000,c,u->{calls.incrementAndGet();return new Reset(u);});fail();}catch(ResilientDownload.Failure e){assertTrue(e.getMessage().contains("duas reconexões"));assertTrue(DownloadFailure.describe("Download",e).contains("duas reconexões"));}assertEquals(3,calls.get());assertEquals(Arrays.asList(1,2),c.retries);assertEquals(Arrays.asList(600L,1200L),c.pauses);}finally{f.delete();}}
 @Test public void cancellationStopsBeforeAnotherRequest()throws Exception{File f=target();byte[] bytes=data(8192,7);Control c=new Control(){@Override public void retry(int n,long stored){cancelled=true;}};try(Server s=new Server((i,h,out)->part(out,bytes,0,bytes.length-1,1024,"\"a\""))){try{fetch(f,10000,c,s::open);fail();}catch(InterruptedIOException expected){}assertEquals(1,s.requests.size());assertEquals(1024,f.length());}finally{f.delete();}}
 @Test public void temporaryServerFailureCanRecover()throws Exception{File f=target();byte[] bytes=data(4096,8);Control c=new Control();try(Server s=new Server((i,h,out)->{if(i==0)headers(out,503,0,"");else full(out,bytes);})){fetch(f,10000,c,s::open);assertArrayEquals(bytes,Files.readAllBytes(f.toPath()));assertEquals(Arrays.asList(1),c.retries);}finally{f.delete();}}
 @Test public void largeFileUsesConsecutiveValidatedRanges()throws Exception{File f=target();byte[] bytes=data((int)ResilientDownload.CHUNK+12345,9);Control c=new Control();try(Server s=new Server((i,h,out)->{long start=offset(h),end=Math.min(bytes.length-1,Long.parseLong(h.get("range").substring(6).split("-")[1]));part(out,bytes,start,end,(int)(end-start+1),"\"a\"");})){fetch(f,12*1024*1024,c,s::open);assertArrayEquals(bytes,Files.readAllBytes(f.toPath()));assertEquals(2,s.requests.size());assertTrue(s.requests.get(1).get("range").startsWith("bytes="+ResilientDownload.CHUNK+"-"));assertTrue(c.retries.isEmpty());}finally{f.delete();}}
 @Test public void oversizedResponseIsRejectedBeforeWriting()throws Exception{File f=target();Control c=new Control();try(Server s=new Server((i,h,out)->headers(out,200,20000,""))){try{fetch(f,10000,c,s::open);fail();}catch(IOException e){assertTrue(e.getMessage().contains("limite"));}assertEquals(0,f.length());assertTrue(c.retries.isEmpty());}finally{f.delete();}}
 @Test public void redirectCannotDowngradeHttps()throws Exception{File f=target();Control c=new Control();try(Server s=new Server((i,h,out)->headers(out,302,0,"Location: http://unsafe.test/file\r\n"))){try{fetch(f,10000,c,s::open);fail();}catch(ProtocolException expected){}assertEquals(1,s.requests.size());assertTrue(c.retries.isEmpty());}finally{f.delete();}}
 @Test public void resetWrappedByTlsIsRecoverable()throws Exception{byte[] bytes=data(1024,10);File f=target();Control c=new Control();AtomicInteger calls=new AtomicInteger();try(Server s=new Server((i,h,out)->full(out,bytes))){fetch(f,10000,c,u->{if(calls.getAndIncrement()==0)return new Reset(u){@Override public int getResponseCode()throws IOException{throw new javax.net.ssl.SSLException("Read failed",new SocketException("Connection reset"));}};return s.open(u);});assertArrayEquals(bytes,Files.readAllBytes(f.toPath()));assertEquals(Arrays.asList(1),c.retries);}finally{f.delete();}}
 @Test public void certificateErrorsAreNotRetried()throws Exception{File f=target();Control c=new Control();AtomicInteger calls=new AtomicInteger();try{try{fetch(f,10000,c,u->{calls.incrementAndGet();return new Reset(u){@Override public int getResponseCode()throws IOException{javax.net.ssl.SSLHandshakeException error=new javax.net.ssl.SSLHandshakeException("certificate verify failed");error.initCause(new java.security.cert.CertificateException("untrusted"));throw error;}};});fail();}catch(javax.net.ssl.SSLHandshakeException expected){}assertEquals(1,calls.get());assertTrue(c.retries.isEmpty());}finally{f.delete();}}
}
